// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
static_assert( __is_trivially_copyable( RenderCamera ), "RenderCamera must stay relocatable" );
static_assert( __is_standard_layout( RenderCamera ), "RenderCamera must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderShip ), "RenderShip must stay relocatable" );
static_assert( __is_standard_layout( RenderShip ), "RenderShip must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderTurret ), "RenderTurret must stay relocatable" );
static_assert( __is_standard_layout( RenderTurret ), "RenderTurret must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderMissile ), "RenderMissile must stay relocatable" );
static_assert( __is_standard_layout( RenderMissile ), "RenderMissile must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderDynamicProp ), "RenderDynamicProp must stay relocatable" );
static_assert( __is_standard_layout( RenderDynamicProp ), "RenderDynamicProp must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderStaticProp ), "RenderStaticProp must stay relocatable" );
static_assert( __is_standard_layout( RenderStaticProp ), "RenderStaticProp must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderCosmeticProp ), "RenderCosmeticProp must stay relocatable" );
static_assert( __is_standard_layout( RenderCosmeticProp ), "RenderCosmeticProp must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderLaser ), "RenderLaser must stay relocatable" );
static_assert( __is_standard_layout( RenderLaser ), "RenderLaser must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RenderExplosion ), "RenderExplosion must stay relocatable" );
